-- ============================================================
-- BASE DE DATOS: ComercioPlus
-- Motor: MySQL 8.0+
-- Dataset sintetico para practicar SQL, JOIN, GROUP BY,
-- subconsultas, vistas, funciones, procedimientos y triggers.
-- ============================================================

DROP DATABASE IF EXISTS ComercioPlus;
CREATE DATABASE ComercioPlus CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ComercioPlus;

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE roles (
 id_rol INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(40) NOT NULL UNIQUE,
 descripcion VARCHAR(150)
) ENGINE=InnoDB;
CREATE TABLE usuarios (
 id_usuario INT PRIMARY KEY AUTO_INCREMENT,
 id_rol INT NOT NULL,
 nombre VARCHAR(80) NOT NULL,
 apellido VARCHAR(80) NOT NULL,
 correo VARCHAR(120) NOT NULL UNIQUE,
 telefono VARCHAR(25),
 fecha_registro DATE NOT NULL,
 estado ENUM('Activo','Inactivo','Suspendido') NOT NULL DEFAULT 'Activo',
 FOREIGN KEY (id_rol) REFERENCES roles(id_rol)
) ENGINE=InnoDB;
CREATE TABLE direcciones (
 id_direccion INT PRIMARY KEY AUTO_INCREMENT,
 id_usuario INT NOT NULL,
 departamento VARCHAR(60) NOT NULL,
 ciudad VARCHAR(80) NOT NULL,
 barrio VARCHAR(80),
 direccion VARCHAR(180) NOT NULL,
 codigo_postal VARCHAR(12),
 es_principal BOOLEAN DEFAULT FALSE,
 FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario)
) ENGINE=InnoDB;
CREATE TABLE clientes (
 id_cliente INT PRIMARY KEY AUTO_INCREMENT,
 id_usuario INT NOT NULL UNIQUE,
 fecha_nacimiento DATE,
 tipo_cliente ENUM('Regular','Frecuente','Corporativo') DEFAULT 'Regular',
 puntos_fidelidad INT NOT NULL DEFAULT 0,
 FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario)
) ENGINE=InnoDB;
CREATE TABLE empleados (
 id_empleado INT PRIMARY KEY AUTO_INCREMENT,
 id_usuario INT NOT NULL UNIQUE,
 cargo VARCHAR(60) NOT NULL,
 salario DECIMAL(12,2) NOT NULL,
 fecha_contratacion DATE NOT NULL,
 FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario)
) ENGINE=InnoDB;
CREATE TABLE categorias (
 id_categoria INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(80) NOT NULL UNIQUE,
 descripcion VARCHAR(200),
 id_categoria_padre INT NULL,
 FOREIGN KEY (id_categoria_padre) REFERENCES categorias(id_categoria)
) ENGINE=InnoDB;
CREATE TABLE marcas (
 id_marca INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(80) NOT NULL UNIQUE,
 pais_origen VARCHAR(60)
) ENGINE=InnoDB;
CREATE TABLE proveedores (
 id_proveedor INT PRIMARY KEY AUTO_INCREMENT,
 razon_social VARCHAR(120) NOT NULL,
 nit VARCHAR(25) NOT NULL UNIQUE,
 contacto VARCHAR(100),
 telefono VARCHAR(25),
 correo VARCHAR(120),
 ciudad VARCHAR(80),
 estado ENUM('Activo','Inactivo') DEFAULT 'Activo'
) ENGINE=InnoDB;
CREATE TABLE productos (
 id_producto INT PRIMARY KEY AUTO_INCREMENT,
 id_categoria INT NOT NULL,
 id_marca INT NOT NULL,
 id_proveedor INT NOT NULL,
 nombre VARCHAR(140) NOT NULL,
 descripcion TEXT,
 sku VARCHAR(30) NOT NULL UNIQUE,
 precio DECIMAL(12,2) NOT NULL,
 costo DECIMAL(12,2) NOT NULL,
 activo BOOLEAN DEFAULT TRUE,
 fecha_creacion DATE NOT NULL,
 FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria),
 FOREIGN KEY (id_marca) REFERENCES marcas(id_marca),
 FOREIGN KEY (id_proveedor) REFERENCES proveedores(id_proveedor)
) ENGINE=InnoDB;
CREATE TABLE almacenes (
 id_almacen INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(80) NOT NULL,
 ciudad VARCHAR(80) NOT NULL,
 direccion VARCHAR(180) NOT NULL,
 capacidad INT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE inventario (
 id_inventario INT PRIMARY KEY AUTO_INCREMENT,
 id_producto INT NOT NULL,
 id_almacen INT NOT NULL,
 existencia INT NOT NULL DEFAULT 0,
 stock_minimo INT NOT NULL DEFAULT 5,
 ultima_actualizacion DATETIME NOT NULL,
 UNIQUE KEY uq_inventario_producto_almacen (id_producto,id_almacen),
 FOREIGN KEY (id_producto) REFERENCES productos(id_producto),
 FOREIGN KEY (id_almacen) REFERENCES almacenes(id_almacen)
) ENGINE=InnoDB;
CREATE TABLE metodos_pago (
 id_metodo INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(50) NOT NULL UNIQUE,
 descripcion VARCHAR(120),
 activo BOOLEAN DEFAULT TRUE
) ENGINE=InnoDB;
CREATE TABLE transportadoras (
 id_transportadora INT PRIMARY KEY AUTO_INCREMENT,
 nombre VARCHAR(100) NOT NULL UNIQUE,
 telefono VARCHAR(25),
 correo VARCHAR(120)
) ENGINE=InnoDB;
CREATE TABLE cupones (
 id_cupon INT PRIMARY KEY AUTO_INCREMENT,
 codigo VARCHAR(30) NOT NULL UNIQUE,
 descripcion VARCHAR(150),
 porcentaje_descuento DECIMAL(5,2) NOT NULL,
 fecha_inicio DATE NOT NULL,
 fecha_fin DATE NOT NULL,
 uso_maximo INT NOT NULL,
 activo BOOLEAN DEFAULT TRUE
) ENGINE=InnoDB;
CREATE TABLE pedidos (
 id_pedido INT PRIMARY KEY AUTO_INCREMENT,
 id_cliente INT NOT NULL,
 id_empleado INT NULL,
 id_direccion INT NOT NULL,
 fecha_pedido DATETIME NOT NULL,
 estado ENUM('Pendiente','Pagado','Enviado','Entregado','Cancelado') NOT NULL,
 subtotal DECIMAL(12,2) NOT NULL,
 descuento DECIMAL(12,2) NOT NULL DEFAULT 0,
 impuesto DECIMAL(12,2) NOT NULL,
 total DECIMAL(12,2) NOT NULL,
 observaciones VARCHAR(250),
 FOREIGN KEY (id_cliente) REFERENCES clientes(id_cliente),
 FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado),
 FOREIGN KEY (id_direccion) REFERENCES direcciones(id_direccion)
) ENGINE=InnoDB;
CREATE TABLE pedido_cupon (
 id_pedido INT NOT NULL,
 id_cupon INT NOT NULL,
 PRIMARY KEY (id_pedido,id_cupon),
 FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
 FOREIGN KEY (id_cupon) REFERENCES cupones(id_cupon)
) ENGINE=InnoDB;
CREATE TABLE detalle_pedido (
 id_detalle INT PRIMARY KEY AUTO_INCREMENT,
 id_pedido INT NOT NULL,
 id_producto INT NOT NULL,
 cantidad INT NOT NULL,
 precio_unitario DECIMAL(12,2) NOT NULL,
 descuento_linea DECIMAL(12,2) NOT NULL DEFAULT 0,
 subtotal DECIMAL(12,2) NOT NULL,
 FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
 FOREIGN KEY (id_producto) REFERENCES productos(id_producto)
) ENGINE=InnoDB;
CREATE TABLE pagos (
 id_pago INT PRIMARY KEY AUTO_INCREMENT,
 id_pedido INT NOT NULL,
 id_metodo INT NOT NULL,
 fecha_pago DATETIME NOT NULL,
 monto DECIMAL(12,2) NOT NULL,
 estado ENUM('Aprobado','Rechazado','Reembolsado','Pendiente') NOT NULL,
 referencia VARCHAR(60) UNIQUE,
 FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
 FOREIGN KEY (id_metodo) REFERENCES metodos_pago(id_metodo)
) ENGINE=InnoDB;
CREATE TABLE envios (
 id_envio INT PRIMARY KEY AUTO_INCREMENT,
 id_pedido INT NOT NULL UNIQUE,
 id_transportadora INT NOT NULL,
 numero_guia VARCHAR(50) NOT NULL UNIQUE,
 fecha_envio DATE,
 fecha_entrega DATE,
 costo_envio DECIMAL(10,2) NOT NULL,
 estado ENUM('Preparando','En_transito','Entregado','Novedad') NOT NULL,
 FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido),
 FOREIGN KEY (id_transportadora) REFERENCES transportadoras(id_transportadora)
) ENGINE=InnoDB;
CREATE TABLE devoluciones (
 id_devolucion INT PRIMARY KEY AUTO_INCREMENT,
 id_pedido INT NOT NULL,
 fecha_solicitud DATE NOT NULL,
 motivo VARCHAR(180) NOT NULL,
 estado ENUM('Solicitada','Aprobada','Rechazada','Procesada') NOT NULL,
 valor_reembolso DECIMAL(12,2) NOT NULL DEFAULT 0,
 FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido)
) ENGINE=InnoDB;
CREATE TABLE detalle_devolucion (
 id_detalle_devolucion INT PRIMARY KEY AUTO_INCREMENT,
 id_devolucion INT NOT NULL,
 id_producto INT NOT NULL,
 cantidad INT NOT NULL,
 observacion VARCHAR(180),
 FOREIGN KEY (id_devolucion) REFERENCES devoluciones(id_devolucion),
 FOREIGN KEY (id_producto) REFERENCES productos(id_producto)
) ENGINE=InnoDB;
CREATE TABLE resenas (
 id_resena INT PRIMARY KEY AUTO_INCREMENT,
 id_cliente INT NOT NULL,
 id_producto INT NOT NULL,
 calificacion TINYINT NOT NULL,
 comentario VARCHAR(500),
 fecha_resena DATE NOT NULL,
 UNIQUE KEY uq_resena_cliente_producto (id_cliente,id_producto),
 FOREIGN KEY (id_cliente) REFERENCES clientes(id_cliente),
 FOREIGN KEY (id_producto) REFERENCES productos(id_producto)
) ENGINE=InnoDB;
CREATE TABLE movimientos_inventario (
 id_movimiento INT PRIMARY KEY AUTO_INCREMENT,
 id_inventario INT NOT NULL,
 tipo ENUM('Entrada','Salida','Ajuste') NOT NULL,
 cantidad INT NOT NULL,
 fecha_movimiento DATETIME NOT NULL,
 referencia VARCHAR(100),
 FOREIGN KEY (id_inventario) REFERENCES inventario(id_inventario)
) ENGINE=InnoDB;

