SET FOREIGN_KEY_CHECKS = 1;

-- VISTAS DE APOYO
CREATE VIEW vw_ventas_por_cliente AS
SELECT c.id_cliente, u.nombre, u.apellido, COUNT(p.id_pedido) AS cantidad_pedidos,
       COALESCE(SUM(CASE WHEN p.estado <> 'Cancelado' THEN p.total ELSE 0 END),0) AS total_comprado
FROM clientes c
JOIN usuarios u ON u.id_usuario=c.id_usuario
LEFT JOIN pedidos p ON p.id_cliente=c.id_cliente
GROUP BY c.id_cliente,u.nombre,u.apellido;

CREATE VIEW vw_stock_bajo AS
SELECT pr.id_producto, pr.nombre, a.nombre AS almacen, i.existencia, i.stock_minimo
FROM inventario i
JOIN productos pr ON pr.id_producto=i.id_producto
JOIN almacenes a ON a.id_almacen=i.id_almacen
WHERE i.existencia <= i.stock_minimo;

CREATE VIEW vw_detalle_ventas AS
SELECT p.id_pedido,p.fecha_pedido,p.estado,cl.id_cliente,u.nombre AS cliente,
       pr.nombre AS producto,dp.cantidad,dp.precio_unitario,dp.subtotal
FROM pedidos p
JOIN clientes cl ON cl.id_cliente=p.id_cliente
JOIN usuarios u ON u.id_usuario=cl.id_usuario
JOIN detalle_pedido dp ON dp.id_pedido=p.id_pedido
JOIN productos pr ON pr.id_producto=dp.id_producto;

-- INDICES ADICIONALES
CREATE INDEX idx_pedidos_fecha ON pedidos(fecha_pedido);
CREATE INDEX idx_pedidos_estado ON pedidos(estado);
CREATE INDEX idx_productos_precio ON productos(precio);
CREATE INDEX idx_resenas_calificacion ON resenas(calificacion);

